parameters.jsCode:
const savedRecipes = $input
  .all()
  .flatMap(item => (Array.isArray(item.json) ? item.json : [item.json]));

if (savedRecipes.length !== 3) {
  throw new Error('Exactly three saved recipes are required for the response.');
}

const quota = $('Consume generation quota').first().json;

const recipes = savedRecipes.map(recipe => ({
  id: recipe.id,
  generationId: recipe.generation_id,
  createdAt: recipe.created_at,
  title: recipe.title,
  summary: recipe.summary,
  cuisineStyle: recipe.cuisine_style,
  dietPreference: recipe.diet_preference,
  cookingTimeCategory: recipe.cooking_time_category,
  cookingTimeMinutes: recipe.cooking_time_minutes,
  portionCount: recipe.portion_count,
  cookingPeopleCount: recipe.cooking_people_count,
  usedIngredientPercentage: recipe.used_ingredient_percentage,
  availableIngredients: recipe.available_ingredients,
  additionalIngredients: recipe.additional_ingredients,
  nutritionPerPortion: recipe.nutrition_per_portion,
  nutritionTotal: recipe.nutrition_total,
  steps: recipe.steps,
  imageUrl: recipe.image_url,
  likesCount: recipe.likes_count,
  isPublic: recipe.is_public,
}));

return [
  {
    json: {
      success: true,
      generationId: recipes[0].generationId,
      remainingGenerations: {
        ip: quota.remaining_for_ip,
        systemWide: quota.remaining_system_wide,
      },
      recipes,
    },
  },
];
